// Headline strip: Bunching score, readings of 135 to 139, readings of 140 to 144.
const root = rpt.mount('.rpt-fud-head');
if (!root) { return; }
const { esc, fmt, num, yes } = rpt;
const r = rpt.rows('A')[0];
const col = (big, cls, color, label, line, title) => '<div' + (title ? ' title="' + esc(title) + '"' : '') + '>'
  + '<div class="rpt-big' + (cls ? ' ' + cls : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + esc(big) + '</div>'
  + '<div class="rpt-label">' + esc(label) + '</div><div class="rpt-line">' + esc(line) + '</div></div>';
if (!r) {
  root.innerHTML = '<div class="rpt-strip3">' + col('—', '', '', 'Bunching score', rpt.NO_DATA) + col('—', '', '', 'Readings of 135 to 139', rpt.NO_DATA)
    + col('—', '', '', 'Readings of 140 to 144', rpt.NO_DATA) + '</div>';
  return;
}
const a = num(r.band_135_139_n) || 0, b = num(r.band_140_144_n) || 0;
const counts = fmt(a) + ' readings of 135 to 139 and ' + fmt(b) + ' readings of 140 to 144';
const flagAt = num(r.flag_score);
let first;
if (yes(r.too_few)) {
  first = col('Too few readings', 'rpt-few', '', 'Bunching score', rpt.needAtLeast(r.min_readings, a + b), counts);
} else if (num(r.score) === null) {
  first = col('—', '', 'var(--flag-bar)', 'Bunching score', r.flag_reason || rpt.NO_DATA, counts);
} else {
  const high = flagAt !== null && num(r.score) >= flagAt;
  first = col(rpt.score(r.score), '', high ? 'var(--flag-bar)' : 'var(--text-primary)', 'Bunching score',
    rpt.score(r.score) + ' readings just under 140 for every 1 just over.' + (flagAt !== null ? ' ' + rpt.score(flagAt) + ' or more is flagged.' : ''), counts);
}
root.innerHTML = '<div class="rpt-strip3">' + first
  + col(fmt(a), '', 'var(--uncontrolled)', 'Readings of 135 to 139', 'just under the line', counts)
  + col(fmt(b), '', 'var(--no-visit)', 'Readings of 140 to 144', 'just over the line', counts) + '</div>';

