// Histogram of the top BP number in 5-point bands; dashed line between 139 and 140.
const frame = (context.panel.data.series || []).find((s) => s.refId === 'A') || (context.panel.data.series || [])[0];
function col(n) { const f = frame && frame.fields.find((x) => x.name === n); if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const lo = col('band_low').map(Number);
const hi = col('band_high').map(Number);
const cnt = col('readings_n').map((v) => Number(v) || 0);
const order = lo.map((v, i) => i).sort((a, b) => lo[a] - lo[b]);
const band = (i) => lo[i] + '–' + hi[i];
const C = chartColors;
const rv = context.grafana && context.grafana.replaceVariables;
const allowed = !rv || rv('${isAllowed}') === '1';
if (!order.length) {
  // No access: the title strip shows the access banner; the chart stays empty.
  return { graphic: allowed ? [{ type: 'text', left: 'center', top: 'middle', style: { text: 'No data for this place.', fontSize: 14, fill: C.muted } }] : [] };
}
const colorOf = (i) => (lo[i] === 135 ? C.uncontrolled : lo[i] === 140 ? C.noVisit : C.estimated);
const NOTE = { 135: 'just under the line', 140: 'just over the line' };
// The dashed line sits on a hidden value axis from 0 to the number of bands, where band k spans k to k + 1,
// so the edge between the 135-139 and 140-144 bars is a whole number.
const k135 = order.findIndex((i) => lo[i] === 135);
const k140 = order.findIndex((i) => lo[i] === 140);
const at = k140 > 0 ? k140 : k135 >= 0 ? k135 + 1 : null;
return {
  animation: false,
  grid: { left: 8, right: 16, top: 34, bottom: 8, containLabel: true },
  tooltip: tip((k) => [fmt(cnt[order[k]]) + ' readings'].concat(NOTE[lo[order[k]]] ? [soft(NOTE[lo[order[k]]])] : []),
    (k) => 'Top BP number ' + band(order[k]), { axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(110,127,141,0.12)' } } }),
  xAxis: [{ type: 'category', data: order.map(band), axisTick: { show: false },
    axisLabel: { color: C.axis, fontSize: 11 }, axisLine: { lineStyle: { color: C.axisLine } } },
  { type: 'value', min: 0, max: order.length, show: false, axisPointer: { show: false } }],
  yAxis: { type: 'value', min: 0, splitNumber: 4, axisLabel: { color: C.axis, fontSize: 11, formatter: (v) => fmt(v) },
    splitLine: { lineStyle: { color: C.grid } } },
  series: [{
    type: 'bar', name: 'Readings', barWidth: '62%',
    data: order.map((i) => ({ value: cnt[i], itemStyle: { color: colorOf(i), borderRadius: [2, 2, 0, 0] } })),
    label: { show: true, position: 'top', color: C.text, fontSize: 12, formatter: (p) => fmt(p.value) }
  }].concat(at === null ? [] : [{
    type: 'line', name: '140', xAxisIndex: 1, data: [[at, 0]], showSymbol: false, silent: true, tooltip: { show: false },
    markLine: {
      silent: true, symbol: ['none', 'none'], animation: false,
      lineStyle: { type: 'dashed', color: C.text, width: 1.5 },
      label: { formatter: '140: high BP starts', position: 'end', color: C.text, fontSize: 12 },
      data: [{ xAxis: at }]
    }
  }])
};

