// Look at these first: at most three flagged facilities, most patients first.
const root = rpt.mount('.rpt-fud-look');
if (!root) { return; }
const { esc, fmt, num, yes } = rpt;
const list = rpt.rows('A').sort((a, b) => (num(b.patients_n) || 0) - (num(a.patients_n) || 0)
  || String(a.org_unit_name).localeCompare(String(b.org_unit_name))).slice(0, 3);
root.innerHTML = '<h3 class="rpt-card-title">Look at these first</h3>' + (list.length
  ? '<ol class="rpt-look">' + list.map((r) => '<li><span class="rpt-look-name">' + esc(r.org_unit_name) + '</span>'
    + (yes(r.looks_fine_check) ? ' <span class="rpt-pill rpt-pill-check">◆ Looks fine, check readings</span>' : '')
    + '<div class="rpt-look-line">' + fmt(r.patients_n) + ' patients · ' + esc(r.flag_reason) + '</div></li>').join('') + '</ol>'
  : '<div class="rpt-muted">' + esc(rpt.NO_FLAGS) + ' Check the table below.</div>');

