// Facility table: Facility, BP controlled, 135–139, 140–144, Bunching score, Why look here.
const root = rpt.mount('.rpt-fud-table');
if (!root) { return; }
const { fmt, num, yes } = rpt;
const counted = (r) => (num(r.band_135_139_n) || 0) + (num(r.band_140_144_n) || 0);
rptTable(root, {
  report: 'fudging',
  rows: rpt.rows('A'),
  caption: 'BP readings just under and just over 140, by facility. Flagged facilities come first.',
  columns: [
    { label: 'BP controlled', num: true, value: (r) => num(r.control_pct), cell: (r) => (num(r.control_pct) === null ? '—' : '<span class="rpt-ctl">' + rpt.pct(r.control_pct) + '</span>') },
    { label: '135–139', num: true, value: (r) => num(r.band_135_139_n), cell: (r) => fmt(r.band_135_139_n) },
    { label: '140–144', num: true, value: (r) => num(r.band_140_144_n), cell: (r) => fmt(r.band_140_144_n) },
    { label: 'Bunching score', num: true, guard: true, value: (r) => num(r.score), cell: (r) => rpt.score(r.score),
      title: (r) => fmt(r.band_135_139_n) + ' readings of 135 to 139 and ' + fmt(r.band_140_144_n) + ' of 140 to 144' }
  ],
  flagNames: () => ['Readings bunch under 140'],
  guardName: 'Too few readings',
  guardReason: (r) => rpt.needAtLeast(r.min_readings, counted(r)),
  check: { text: '◆ Looks fine, check readings', when: (r) => yes(r.looks_fine_check) },
  alsoOn: ['titration'],
  size: (r) => num(r.readings_n)
});
